import (
"encoding/json"
「fmt」
)
type Install struct {
日付文字列 `json:"date"`
バージョン文字列 `json:"version"`
}
type InstallData struct {
Installs []Install `json:"installs"`
}
func main() {
jsonData := `{
「データ」:{
