"バージョン":"16.44"
}, { "date":"2021-12-01",
"バージョン":"16.45"
}
]
}
}`
var installData InstallData
err := json.Unmarshal([]byte(jsonData),&installData)
if err != nil {
fmt.Println(err)
リターン
} fmt.Println("Installation History:")
for _,install := range installData.Installs {
