@dish_orders.delete(name)
終わり
終わり
def calculate_total_cost(*dishes)
dishes.each do |dish|
if @menu.key?(dish)
@total_cost += @menu[dish]
@dish_orders[dish] += 1
終わり
終わり
@total_cost
終わり
ポピュラーディッシュを消す
popularity_scores = {}
total_orders = @dish_orders.values.sum.to_f
@dish_orders.each do |dish,orders|
popularity_scores[dish] = (orders / total_orders) * 100
終わり
popularity_scores.sort_by { |_,score| -score }.to_h
終わり
