int main() {
std::vector mylist = {1,2,3,4,5};
int sum = std::accumulate(mylist.begin(),mylist.end(),0);
mylist.push_back(sum);
for (int i = 0;i < mylist.size();i++) {
std::cout << mylist[i] << " ";
}
