instruction:
SQL データベースでは、n が 10 より大きい素数である複素数の n 番目の根をどのように決定しますか?Go でこれを実装する等価なコードを提供できますか?
ここでは、極形の複素数の n 番目の根を計算するサンプルの Go コードです。
パッケージ メイン
import (
「fmt」
「マット」
「math/cmplx」
) func nthRootOfComplexNumber(z complex128,n int) complex128 {
// 複素数を極形に変換する
r := cmplx.Abs(z)
theta := cmplx.Phase(z)
// 大きさの n 番目の根を計算する
nthRootOfMagnitude := cmplx.Pow(r,1/float64(n))
// 統一のn番目の根を計算する
nthRootsOfUnity := make([]complex128,n)
for k := 0;k < n;k++ {
thetaK := theta + 2*math.Pi*float64(k)/float64(n)
nthRootsOfUnity[k] = cmplx.Rect(nthRootOfMagnitude,thetaK)
}
// return the nth root closest to the real axis
minDistanceFromRealAxis := math.Inf(1)
var nthRoot 複合体128
for _,root := range nthRootsOfUnity {
distanceFromRealAxis := cmplx.Abs(complex(real(root),0))
distanceFromRealAxis < minDistanceFromRealAxis {
minDistanceFromRealAxis = distanceFromRealAxis
nthRoot = root
}
}
return nthRoot
}
func main() {
z := 複合(1,1)
n:= 11
nthRoot :=nthRootOfComplexNumber(z,n)
fmt.Printf("The %d-th root of %v is %v",n,z,nthRoot)
} このコードをSQL データベースで動作するように変更する方法は?

response:
このコードを SQL データベースで使用するには、複合数と素数を入力として取り込み、複合数の n 番目のルートを返すストレージされたプロシージャを作成する必要があります。
Go コードを SQL データベースで動作させるための変更方法の例を以下に示します。
``` CREATE FUNCTION nth_root_of_complex_number(z complex,n int) 複素を$$として返します
宣言
rフロート;
テータフロート
nth_root_of_magnitude float;
nth_roots_of_unity complex[];
k int;
theta_k float;
distance_from_real_axis float;
min_distance_from_real_axis float = 9999999;
nth_root 複合体
BEGIN
-- 複素数を極形に変換します
r := sqrt(power(z.real,2) + power(z.imaginary,2));
theta := atan(z.imaginary / z.real);
if z.real < 0 then
theta := theta + pi();
end if;
if z.real >= 0 and z.imaginary < 0 then
theta := theta + 2 * pi();
end if;
マグニチュードの n 番目の根を計算します
nth_root_of_magnitude := power(r,1 / n);
ユニティのn番目の根を計算する
nth_roots_of_unity := array_fill(0::complex,n);
k を 0..n-1 ループに
theta_k := theta + 2 * pi() * k / n;
nth_roots_of_unity[k] := polar_to_complex(nth_root_of_magnitude,theta_k);
エンドループ
-- 実軸に最も近い n 番目の根を返します
k を 1..n ループに
distance_from_real_axis := abs(nth_roots_of_unity[k].real);
distance_from_real_axis < min_distance_from_real_axis なら
min_distance_from_real_axis := distance_from_real_axis;
nth_root := nth_roots_of_unity[k];
end if;
エンドループ
return nth_root;
END;
$$ LANGUAGE plpgsql;
``` この格納されたプロシージャは、複素数 `z` と素数 `n` を取り込み、複素数の形式で `z` の n 番目の根を返します。
この保存されたプロシージャを使用するには、以下のように呼び出します。
```
SELECT nth_root_of_complex_number(complex(1,1),11);
``` これは複素数 (1,1) の 11 番目のルートを返します。

