ここでは、可能な解決策があります。
int[] nums = { 5,4,3,2,7,6,1 };
int n = nums.Length;
int[] dp = new int[n];
int maxLen = 0;
for (int i = 0;i < n;i++)
{dp[i] = 1;
for (int j = 0;j < i;j++)
{
if (nums[i] > nums[j])
{ dp[i] = Math.Max(dp[i],dp[j] + 1);
} maxLen = Math.Max(maxLen,dp[i]);
}
if (maxLen < 3)
{ Console.WriteLine("少なくとも3つの要素の増大するサブシーケンスはありません。
}
else
{ Console.WriteLine("少なくとも3つの要素の最長増加サブシーケンスの長さは{0}.",maxLen);

