ここでは、MySQL データベースからデータを取得し、HTML ページにテーブル形式で表示する Go コードの例を示します。
[コードに移動]
パッケージ メイン
import (
"database/sql"
「fmt」
"html/template"
「ログ」
"net/http"
_ "github.com/go-sql-driver/mysql"
)
type Person struct {
名前文字列
年齢イント
}
func main() {
http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request) {
db,err := sql.Open("mysql","username:password@tcp(localhost:3306)/dbname")
if err != nil {
log.Fatal(err)
}
defer db.Close()
rows,err := db.Query("SELECT name,age FROM people")
if err != nil {
log.Fatal(err)
}
defer rows.Close()
var people []Person
for rows.Next() {
var p 人物
err := rows.Scan(&p.Name,&p.Age)
if err != nil {
log.Fatal(err)
} people = append(people,p)
}
if err := rows.Err();err != nil {
log.Fatal(err)
} tmpl,err := template.New("index").Parse(`
人物
名前 年齢 |
〜〜〜〜〜〜〜〜〜〜〜〜〜〜〜〜〜〜〜
名前 年齢 年齢 年齢
エンド(エンド)
`)
if err != nil {
log.Fatal(err)
} err = tmpl.Execute(w,people)
if err != nil {
log.Fatal(err)
