もちろん、ここでは、データベース内の「定義」テーブルをクエリし、単語「adroit」の同義語と同義語の定義を取得するSwiftコードのサンプルです。また、定義が6ヶ月未満であるかどうかをチェックします。
速い
import Foundation
import SQLite
// Open the database
let db = try Connection("/path/to/database.sqlite")
// テーブルを定義する
let definitions = Table("definitions")
// 列を定義する
let id = Expression("id")
let word = Expression("word")
let definition = Expression("definition")
let synonym = Expression("synonym")
let antonym = Expression("antonym")
let date = Expression("date")
// "adroit"という言葉の同義語と同義語の定義のためのデータベースをクエリ
let sixMonthsAgo = Calendar.current.date(byAdding:.month,value:-6,to:Date())!
let query = definitions.select(definition,synonym,antonym)
.filter(word == "adroit")
.filter(date >= sixMonthsAgo)
// クエリを実行して結果を印刷
for row in try db.prepare(query) {
print("Definition:(row[definition])")
print("Synonym:(row[synonym])")
print("Antonym:(row[antonym])")
} // 「アドロイト」という言葉の起源を調べる
let originQuery = definitions.select(definition)
.filter(word == "adroit")
.filter(date >= sixMonthsAgo)
.filter(definition.like("%Origin%"))
// クエリを実行して結果を印刷
if let originRow = try db.pluck(originQuery) {
print("Origin:(originRow[definition])")
} // 20世紀以前に書かれた文学作品の文の中で「アドロイト」という単語の使い方を調べる
let usageQuery = definitions.select(definition)
.filter(word == "adroit")
.filter(date >= sixMonthsAgo)
.filter(definition.like("%literary work%19th century%"))
// クエリを実行して結果を印刷
if let usageRow = try db.pluck(usageQuery) {
print("Usage:(usageRow[definition])")
} ``` "/path/to/database.sqlite" をデータベースファイルへの実際のパスに置き換える必要があることに注意してください。また、テーブルと列名がデータベースの実際の名前と一致していることを確認してください。

