public string @ObsStatus { get;set;}
public List Data { get;set;}
}
public class Data
{ public string @Time { get;set;}
public string @Value { get;set;}
} 公開クラスプログラム
{
static async Task Main(string[] args)
{
var client = new HttpClient();
var response = await client.GetAsync("https://stats.oecd.org/SDMX-JSON/data/MEI_FIN/JP.TOK+OSA+YOK.GDP+B1_GE.CUR+VOBARSA.Q/all?startTime=2010-Q1&endTime=2021-Q1");
var content = await response.Content.ReadAsStringAsync();
var gdp = JsonConvert.DeserializeObject(content);
