同じ推測ゲームで、許可された推測の最大数を超えた場合、ユーザーにメッセージを表示するために与えられた[Latex]コードを変更します。許容される推測の最大数は、ゲームの開始時にユーザーによって決定されるべきです。現在の [Latex] コードは以下のとおりです。
begin{lstlisting}[language=Java]
import java.util.Random;
import java.util.Scanner;
public class NumberGuessingGame {
public static void main(String[] args) {
Random rand = new Random();
Scanner scanner = new Scanner(System.in);
System.out.println("Enter the maximum number of guesses allowed:");
int maxGuesses = scanner.nextInt();
int numberToGuess = rand.nextInt(100) + 1;
int userGuess;
boolean guessedCorrectly = false;
int numGuesses = 0;
while (!guessedCorrectly && numGuesses < maxGuesses) {
System.out.println("Guess a number between 1 and 100:");
userGuess = scanner.nextInt();
numGuesses++;
if (userGuess == numberToGuess) {
System.out.println("おめでとうございます!あなたは数を推測しました。
guessedCorrectly = true;
} else if (userGuess < numberToGuess) {
System.out.println("あなたの推測は低すぎる。もう一度試してみてください」);
} else {
System.out.println("あなたの推測は高すぎる。もう一度試してみてください」);
}
}
if (!guessedCorrectly && numGuesses >= maxGuesses) {
System.out.println("ごめんなさい、許容される推測の最大数を超えました。
} scanner.close();
} } end{lstlisting

