ここでは、トップ5のオンラインストアからデータを取得し、価格でソートするJavaコードのサンプルです。
import java.util.*;
import java.io.*;
import java.net.*;
public class ProductFetcher {
public static void main(String[] args) throws Exception {
String product = "iPhone 12";// replace with your product name
String[] stores = {"Amazon","eBay","Walmart","Best Buy","Target"};// top 5 stores
Map prices = new HashMap();// store prices
for (String store:stores) {
String url = "https://www." + store.toLowerCase() + ".com/search?q=" + product;
String html = fetchHTML(url);// fetch HTML code of the store's search page
double price = extractPrice(html);// extract price from HTML code
prices.put(store,price);// add price to map
}

// sort prices by ascending order
List> list = new LinkedList>(prices.entrySet());
Collections.sort(list,new Comparator>() {
public int compare(Map.Entry o1,Map.Entry o2) {
return (o1.getValue()).compareTo(o2.getValue());
}
});

// print sorted prices
for (Map.Entry entry:list) {
System.out.println(entry.getKey() + ":" + entry.getValue());
} } // 指定したURLの HTML コードを取得
public static String fetchHTML(String url) throws Exception {
URLConnection conn = new URL(url).openConnection();
InputStream is = conn.getInputStream();
BufferedReader reader = new BufferedReader(new InputStreamReader(is));
String line = null;
StringBuilder sb = new StringBuilder();
while ((line = reader.readLine()) != null) {
sb.append(line);
}
return sb.toString();
}

// extract price from HTML code
public static double extractPrice(String html) {
// 店舗の検索ページのHTMLコードに基づいた独自の価格抽出ロジックを実装
// これはただのダミー実装です
return Math.random() * 1000;// return a random price between 0 and 1000
}

