```csharp
using System;
Newtonsoft.Json.Linqを使用しています。
クラスプログラム
{
static void Main(string[] args)
{ // 例 JSON オブジェクト
string json = @"
{ ""name"":""John Smith"",
「年齢」:30,
""アドレス"":{
""通り"":""123メインストリート"",
""都市"":""ニューヨーク"",
""国"":""NY"",
""zip"":""10001""
}, ""phoneNumbers"":[
{ ""タイプ"":""ホーム"",
""番号":""555-1234""
},
{
""type"":""work"",
「番号」:""555-5678""
} ] }"; // JSON オブジェクトを解析
JObject obj = JObject.Parse(json);
// LINQ を使用して JSON オブジェクトをクエリし、"city" フィールドの値を抽出します
string city = (string)obj.SelectToken("address.city");
// 結果を印刷
Console.WriteLine(city);
} ``` この例では、Newtonsoft.Json.Linq ライブラリを使用して、JSON オブジェクトを JObject に解析します。次に、LINQ を使用して JSON オブジェクトをクエリし、 SelectToken メソッドを呼び出し、抽出したいフィールドにパスを渡して "address.city" フィールドの値を抽出します。最後に、結果を文字列にキャストし、コンソールに印刷します。

