C#プログラムを作成して、"dowager"の文字を5つの共通名詞に並べ替える verbal puzzle を解決する方法は?
ここではサンプルコードです。
string word = "dowager";
char[] letters = word.ToCharArray();
Array.Sort(letters);
string sortedWord = new string(letters);
Console.WriteLine("Sorted letters:" + sortedWord);
// すべての変数のリストを作成する
List permutations = new List();
Permute("",sortedWord,permutations);
// フィルターリストに5文字の単語のみを含む
List fiveLetterWords = permutations.FindAll(w => w.Length == 5);
// Print the list of five letter words
Console.WriteLine("Five letter words:");
foreach (5文字列の文字列単語)
{ Console.WriteLine(word);
} // 文字列のすべての変数を見つける方法
private static void Permute(string prefix,string suffix,List permutations)
{ int n = suffix.Length;
if (n == 0) permutations.Add(prefix);
他にも
{
for (int i = 0;i < n;i++)
Permute(prefix + suffix[i],suffix.Substring(0,i) + suffix.Substring(i + 1),permutations);
}

