import java.sql.SQLException;
公開クラス BaseballDataStorage {
private static final String JDBC_DRIVER = "com.mysql.jdbc.Driver";
private static final String DB_URL = "jdbc:mysql://localhost/baseball";
private static final String USER = "username";
private static final String PASS = "password";
public static void main(String[] args) {
Connection conn = null;
PreparedStatement stmt = null;
try {
Class.forName(JDBC_DRIVER);
conn = DriverManager.getConnection(DB_URL,USER,PASS);
String sql = "INSERT INTO players (name,team,position,age) VALUES (?,?,?,?)";
stmt = conn.prepareStatement(sql);
stmt.setString(1,"Mike Trout");
stmt.setString(2,"Los Angeles Angels");
stmt.setString(3,"Center Field");
stmt.setInt(4,29);
stmt.executeUpdate();
} catch (Exception e) {
e.printStackTrace();
} finally {
try {
if (stmt != null) stmt.close();
if (conn != null) conn.close();
} catch (SQLException se) {
