```java
import org.apache.spark.SparkConf;
import org.apache.spark.api.java.JavaRDD;
import org.apache.spark.api.java.JavaSparkContext;
import org.apache.spark.sql.DataFrame;
import org.apache.spark.sql.SQLContext;
公開クラス BaseballDataAnalysis {
public static void main(String[] args) {
SparkConf conf = new SparkConf().setAppName("BaseballDataAnalysis").setMaster("local");
JavaSparkContext sc = new JavaSparkContext(conf);
SQLContext sqlContext = new SQLContext(sc);
DataFrame df = sqlContext.read().format("jdbc").option("url","jdbc:mysql://localhost/baseball")
.option("driver","com.mysql.jdbc.Driver").option("dbtable","players").option("user","username")
.option("password","password").load();
JavaRDD names = df.javaRDD().map(row -> row.getString(0));
long numPlayers = names.count();
System.out.println("Number of players:" + numPlayers);
sc.stop();
} ``` このコードは、Apache Sparkを使用してMySQLデータベースからデータを読み取り、プレイヤーの数を「プレイヤー」テーブルにカウントします。
