diet = data.Diet;
% 平均運動量と食事量を計算
avg_exercise = mean(exercise);
avg_diet = mean(diet);
% データに基づいたモチベーションのヒントを生成
avg_exercise < 30 であれば
fprintf('ヒント1:毎日少なくとも30分運動してみてください。n');
終わり
if avg_diet > 2000
fprintf('ヒント2:毎日2000カロリー以下を消費することを目標にします。n');
終わり
if std(exercise) > 10
fprintf('ヒント3:退屈を避けるためにあなたの運動のルーチンをミックスする。n');
終わり
if std(diet) > 500
fprintf('ヒント4:あなたの食事を興味深く保つために新しい健康的なレシピを試してください。n');
終わり
if avg_exercise < 30 && avg_diet > 2000
