ここでは、Javaコードの例を示します。
import java.util.Scanner;
公共クラス 廃棄物削減 {
public static void main(String[] args) {
// 毎日の廃棄物生産を計算する機能
int calculateWaste(int numPeople) {
int wastePerPerson = 2;// in pounds
return numPeople * wastePerPerson;
}

Scanner scanner = new Scanner(System.in);
System.out.print(「世帯に何人が住んでいますか?"); int numPeople = scanner.nextInt();
scanner.close();
// Calculate waste production per day
int waste = calculateWaste(numPeople);
