fetch(forecastUrl)
.then(response => response.json())
.then(data => {
const forecast = data.list.map(item => {
return { date:item.dt_txt,weather:item.weather[0].main,temp:item.main.temp,humidity:item.main.humidity };
});

// Generate statement based on current weather and five-day forecast
let statement = "";
if (currentWeather === "Rain") {
