ここでは、クイックソートアルゴリズムを使用したサンプルコードです。
void quickSort(int arr[],int low,int high) {
if (low < high) {
int pivot = arr[high];
int i = (low - 1);
for (int j = low;j <= high - 1;j++) {
if (arr[j] > pivot) {
i++;
swap(arr[i],arr[j]);
} swap(arr[i + 1],arr[high]);
int pi = i + 1;
quickSort(arr,low,pi - 1);
quickSort(arr,pi + 1,high);
} } 関数を使用するには、次のように呼び出します。
