``` func evaluateFitness(individual:Individual) -> Double {
// 個々の遺伝子でゲームを実行
let game = Game(individual.genes)
let score = game.run()
// ゲームスコアに基づいてフィットネスを計算
let fitness = Double(score) / Double(game.maxScore)
リターンフィットネス
} ``` この例では、`Game` クラスは、配列の遺伝子を入力し、それらを使用してゲームのプレイヤーの動作を制御します。`run()` メソッドはゲームを実行し、スコアを返します。スコアを最大値で分割して0 から 1 までのフィットネス値を取得します。
最後に、彼らのフィットネススコアに基づいて人口を進化させる機能が必要です。この関数は、`Individual` オブジェクトの配列を入力として取り、進化した個々の新しい配列を返します。この例では、単純な遺伝アルゴリズムを使用して、人口から最も適した個体を選択し、その遺伝子を組み合わせて新しい個体を作成します。
``` func evolvePopulation(population:[Individual]) -> [Individual] {
// フィットネスによって人口をソート
let sortedPopulation = population.sorted { $0.fitness > $1.fitness }
// 繁殖に最適な個体を選択
let breedingPool = Array(sortedPopulation.prefix(Int(Double(sortedPopulation.count) * 0.2)))
