Amazon Product Advertising API in Java を使用して、Lenovo ThinkPad X1 Carbon 2020 の現在の価格を取得するにはどうすればよいですか?検索クエリを実行し、アイテムの現在の価格を返すことができる例[Javaコード]を提供することができますか?さらに、アイテムの価格が一定の閾値を下回ると通知を送信する機能を追加できますか?
Amazon Product Advertising API を使用して、Lenovo ThinkPad X1 Carbon 2020 の現在の価格を取得し、価格が指定された閾値以下に低下したときに通知を送信する [Java コード] の例です。
import java.util.*;
import com.amazonaws.*;
import com.amazonaws.auth.*;
import com.amazonaws.services.*;
import com.amazonaws.services.apa.*;
import com.amazonaws.services.apa.model.*;
public class AmazonProductAPI {
public static void main(String[] args) {
AWSCredentials credentials = new BasicAWSCredentials("ACCESS_KEY","SECRET_KEY");
AmazonProductAdvertisingClient amazonClient = new AmazonProductAdvertisingClient(credentials);
ItemLookupRequest request = new ItemLookupRequest();
request.setIdType("ASIN");
request.getItemId().add("B084KJ7ZG9");
request.getResponseGroup().add("OfferSummary");
ItemLookupResponse response = amazonClient.itemLookup(request);
String price = response.getItems().get(0).getOfferSummary().getLowestNewPrice().getFormattedPrice();
//価格が1000ドル以下になると通知を送信
if(Double.parseDouble(price.substring(1)) < 1000.0) {
sendNotification("Lenovo ThinkPad X1 Carbon 2020の価格は$1000以下に低下しました。現在の価格は「+価格」です。
}
}
public static void sendNotification(String message) {
//Code to send notification
}

