入力と出力を表すためにJSON データを用いて、合計が 3 で分割される正整数のスライスですべてのペアを検索するために、Go でアルゴリズムを実装する方法は?入力配列は以下の形式になります。
{ "array":[
{"値":3},
{"値":4},
{"値":5},
{"値":6},
{"値":7},
{"値":8},
{"値":9},
{"値":10},
{"値":11},
{"値":12}
] } 出力は JSON 形式で以下のように表示されるべきです。
{「ペア」:[
{"ペア":[3,9]},
{"ペア":[4,8]},
{"ペア":[5,7]},
{"ペア":[6,12]}
] } Go のマップデータ構造を使用してアルゴリズムを実装してください。Go コードの開始例を以下に示します。
func findPairs(input string) string {
// Go データ構造に JSON 入力を解析
var data map[string]interface{}
err := json.Unmarshal([]byte(input),&data)
if err != nil {
"Error parsing input JSON"を返します
}

// Extract the array of values from the data
array := data["array"].([]interface{})
// これまで見た値をマップで保存する
seen := make(map[int]bool)
// スライスを使用して、3の倍数に加算するペアを格納する
ペア:= make([][]int,0)
// 配列を繰り返し、ペアを確認する
for _,item := range array {
value := int(item.(map[string]interface{})["value"].(float64))
if seen[(3-value%3)%3] {
pairs = append(pairs,[]int{(3-value%3)%3,value})
} seen[value% 3] = true
}

// Convert the pairs slice to JSON and return it
output,_ := json.Marshal(map[string]interface{}{"pairs":pairs})
return string(output)

response:
ここでは、マップデータ構造を使用してGoのアルゴリズムの実装です。
``` パッケージメイン
import (
"encoding/json"
「fmt」
) func findPairs(input string) string {
// Go データ構造に JSON 入力を解析
var data map[string]interface{}
err := json.Unmarshal([]byte(input),&data)
if err != nil {
"Error parsing input JSON"を返します
}
// Extract the array of values from the data
array := data["array"].([]interface{})
// これまで見た値をマップで保存する
seen := make(map[int]bool)
// スライスを使用して、3の倍数に加算するペアを格納する
ペア:= make([][]int,0)
// 配列を繰り返し、ペアを確認する
for _,item := range array {
value := int(item.(map[string]interface{})["value"].(float64))
if seen[(3-value%3)%3] {
pairs = append(pairs,[]int{(3 - value%3) % 3,value})
} seen[value% 3] = true
}
// Convert the pairs slice to JSON and return it
output,_ := json.Marshal(map[string]interface{}{"pairs":pairs})
return string(output)
}
func main() {
input := `{
"array":[
{"値":3},
{"値":4},
{"値":5},
{"値":6},
{"値":7},
{"値":8},
{"値":9},
{"値":10},
{"値":11},
{"値":12}
] }` output := findPairs(input)
fmt.Println(出力)
} ``` このプログラムは、入力の JSON 文字列を Go データ構造に解析し、値の配列を通って繰り返し、3 の倍数のペアを検索します。これまで見た値をマップで保存し、基準を満たすペアをスライスで保存します。最後に、ペアスライスをJSONに変換し、文字列として返します。与えられた入力のプログラムの出力は次のとおりです。
``` {"pairs":[[0,3],[2,9],[1,4],[1,8],[2,5],[0,6],[2,7],[0,12]]}
```

