var response:String
var puzzle:String
init(intensity:Double,threshold:Double,response:String,puzzle:String) {
自己.intensity = intensity
self.threshold = threshold
self.response = 応答
self.puzzle = puzzle
} func react(answer:String) -> String {
if answer == puzzle && intensity >= threshold {
返答
} else {
戻る "それを感じていない"
}
}
}
