func getHistoricalWeatherData(date:Date,location:String,latitude:Double,longitude:Double) {
// 日付パラメータをフォーマットする日付フォーマッターを作成
let dateFormatter = DateFormatter()
dateFormatter.dateFormat = "yyyy-MM-dd"
