「fmt」
)

type Character struct {
名前文字列
職業文字列
}

type Story struct {
メイン文字文字
競合文字列
分解能文字列
}

func main() {
mc := Character{Name:"Mr.Evans",職業:"講師"}
var 競合文字列
fmt.Println("紛争を入力する:")
fmt.Scan(&conflict)
var 解像度文字列
fmt.Println("解像度を入力する:")
fmt.Scan(解像度)
s := Story{MainCharacter:mc,Conflict:conflict,Resolution:resolution}
fmt.Printf("%s は コントラクト:%s に直面する %s です。%s.n",s.MainCharacter.Name,s.MainCharacter.Occupation,s.Conflict,s.Resolution)
} ``` この変更されたコードを使用すると、ユーザはストーリーの独自のコントラクトと解像度を入力することができます。fmt.Scan() 関数は、ストーリーを続行する前にユーザ入力を待つことができます。

