timeSpentTile := powerbi.Tile{
タイトル:「プラットフォームに費やされた時間」
VisualType:powerbi.VisualTypeTable,
データセットID:"",
タイルタイプ:Powerbi.TileTypePowerBI,
Config:map[string]interface{}{
"columns":[]string{"Time Spent","Student Name","Course Name"},
"filters":[]string{"Course Name","Start Date","End Date"},
},
}
// Add tile to dashboard
dashboard.Tiles = append(dashboard.Tiles,timeSpentTile)
