```
const apiKey = 'your_api_key_here';
const url = `https://api.openweathermap.org/data/2.5/weather?q=Chandigarh&appid=${apiKey}`;
const forecastUrl = `https://api.openweathermap.org/data/2.5/forecast?q=Chandigarh&appid=${apiKey}`;
fetch(url)
.then(response => response.json())
.then(data => {
const currentWeather = data.weather[0].description;
console.log(`Current weather:${currentWeather}`);
})
.catch(error => console.error(error));
fetch(forecastUrl)
.then(response => response.json())
.then(data => {
const forecastedWeather = data.list[7].weather[0].description;
console.log(`Forecasted weather:${forecastedWeather}`);
})
.catch(error => console.error(error));
