```C#
using System;
名前空間 DiceGame
{
class Program
{
static void Main(string[] args)
{
Random rnd = new Random();
int rolls = 0;
int AliceTarget = rnd.Next(10,21);
int BobTarget = rnd.Next(10,21);
bool AliceWon = false;
while (!AliceWon)
{ロール++;
