Swift を使用して、指定された XML データから特定の要素を抽出するには、Apple が提供する `XMLParser` クラスを使用することができます。ここではこれを達成するためのコードです:
速い
import UIKit
class ViewController:UIViewController,XMLParserDelegate {
var elementName:String = ""
var name:String = ""
var age:String = ""
var people:[[String:String]] = []
override func viewDidLoad() {
super.viewDidLoad()
let xmlString = """
ジョン・ドー
30名の男性
ジェーン・ドー
28女性
ボブ・スミス
42男
"""
if let data = xmlString.data(using:.utf8) {
let parser = XMLParser(data:data)
parser.delegate = 自己
parser.parse()
} } // MARK:- XMLParserDelegate メソッド
func parser(_ parser:XMLParser,didStartElement elementName:String,namespaceURI:String?,qualifiedName qName:String?,attributes attributeDict:[String:String] = [:]) {
self.elementName = elementName
if elementName == "person" {
name = ""
age = ""
} func parser(_ parser:XMLParser,foundCharacters string:String) {
スイッチ要素名 {
case "name":name += string
case "age":age += string
デフォルト:ブレーク
} func parser(_ parser:XMLParser,didEndElement elementName:String,namespaceURI:String?,qualifiedName qName:String?) {
if elementName == "person" {
let person = ["name":name,"age":age]
people.append(人)
} } func parserDidEndDocument(_ parser:XMLParser) {
displayTable()
} // MARK:- ヘルパーメソッド
func displayTable() {
var table = "| Name | Age |n|-----------|-----|n"
人間を対象として {
let name = person["name"] ??""
let age = person["age"] ??"テーブル +="|(名前) |(年齢) |n"
}
print(table)
} } ``` このコードは、`XMLParserDelegate` プロトコルに準拠するビューコントローラを定義します。`viewDidLoad` メソッドは XML 文字列を初期化し、そのデータで `XMLParser` オブジェクトを作成します。次に、XMLParserDelegate メソッドが実装され、XML データを解析し、各人の名前と年齢を抽出します。解析が完了すると `parserDidEndDocument` メソッドが呼び出され、 Markdown 構文を使用してテーブルにデータをフォーマットするために `displayTable` メソッドが呼び出されます。結果のテーブルはコンソールに印刷されます。

