import java.io.File;
import java.io.FileNotFoundException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
public class WordFrequencyCounter {
public static void main(String[] args) {
Map wordFrequency = new HashMap<>();
Set stopWords = new HashSet<>();
stopWords.add("and");
stopWords.add("the");
stopWords.add("a");
try {
File file = new File("shakespeare.txt");
Scanner scanner = new Scanner(file);
while (scanner.hasNextLine()) {
String line = scanner.nextLine();
文字列[] words = line.split("W+");
for (String word:words) {
if (!stopWords.contains(word.toLowerCase())) {
if (!wordFrequency.containsKey(word)) {
wordFrequency.put(word,1);
} else {
wordFrequency.put(word,wordFrequency.get(word) + 1);
} } } scanner.close();
} catch (FileNotFoundException e) {
System.out.println("File not found.");
}
for (String word:wordFrequency.keySet()) {
System.out.println(word + ":" + wordFrequency.get(word));
} } ``` このバージョンのコードでは、周波数カウントから除外したい単語を含む `stopWords` と呼ばれる HashSet を作成します。次に、`contains()` メソッドを使用してこのセットに対して各単語をチェックし、停止単語ではない場合は HashMap に追加します。また、各単語を`toLowerCase()` メソッドを使用して小文字に変換し、停止単語のすべてのバリエーションをキャッチできるようにします。

