```
const mysql = require('mysql');
// create a connection to the database
const connection = mysql.createConnection({
host:'localhost',
user:'username',
パスワード:'password',
データベース:'database_name'
});
// connect to the database
connection.connect();
// SQLクエリを実行する
const query = `
SELECT countries.name AS country_name,countries.capital,seas.name AS sea_name
FROM諸国
INNER JOIN countries_seas ON countries.id = countries_seas.country_id
INNER JOIN seas ON countries_seas.sea_id = seas.id
seas.name = 「地中海」
`;
connection.query(query,(error,results) => {
if (error) throw error;
// HTML テーブルを生成
let tableHtml = '
| 国 | 首都 |
| --- | --- |
';
results.forEach(result => {
tableHtml += `| ${result.country_name} | ${result.capital} |
`; }); tableHtml += '
'; // HTML テーブルを表示
console.log(tableHtml);
// close the database connection
connection.end();
}); ``` このコードは MySQL データベースへの接続を作成し、必要なデータを取得するために SQL クエリを実行し、取得したデータを用いて HTML テーブルを生成し、HTML テーブルを表示します。特定の要件に基づいてデータを取得するためにSQLクエリを変更できます。

