popup.remove();
});
// Set a session storage item to indicate that the pop-up has been shown
sessionStorage.setItem('popupShown',true);
} ``` コード内の HTML と CSS を変更することで、ポップアップのメッセージとスタイルをカスタマイズできます。このコードを使用するには、HTMLドキュメントのヘッドまたはボディにあるスクリプトタグに追加できます。

