function result = evaluate(num1,num2,operator)
% num1:最初の数
% num2:2番目の番号
%オペレーター:オペレーター (+,-,*,/)
% result:評価結果
スイッチ・オペレーター
case '+'
result = num1 + num2;
case '-'
result = num1 - num2;
case '*'
result = num1 * num2;
case '/'
もし num2 == 0 なら
error('Divide by zero error');
他にも
result = num1 / num2;
終わり
そうでなければ
error('Invalid operator');
終わり
