MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);
if (result == DialogResult.Yes)
{ // ユーザーは招待状を拒否する理由として「興味がない」を選択しました
txtReason.Text = "興味がない";
} else if (result == DialogResult.No)
{ // ユーザーは招待を拒否する理由として「バッシー」を選択しました
txtReason.Text = "Busy";
}
else if (result == DialogResult.Cancel)
{ // 招待状を拒否する理由として「その他」を選択したユーザ
txtReason.Text = "その他";
} // 追加コメントを入力するようユーザーにプロンプトするダイアログボックスを表示
string additionalComments = "";
InputBox("追加コメント","任意の追加コメントを入力してください:",ref追加コメント);
// 理由と追加のコメントをデータベースに保存
SaveToDatabase(txtReason.Text,additionalComments);
} private void SaveToDatabase(string reason,string additionalComments)
{ // データベースに理由と追加コメントを保存するコード
} private DialogResult InputBox(string title,string promptText,ref string value)
{ // 追加コメントを入力するようにユーザーにプロンプトするダイアログボックスを表示するコード
