)
func main() {
words := []string{"Sky","High","love","grows","Sun","sets","my","for","you"}
// 最初の行:1つの単語
fmt.Println(words[0])
// 2行目:3つの単語
fmt.Println(strings.Join(words[1:4]," "))
// 第3行:5つの単語
fmt.Println(strings.Join(words[4:]," "))
} ``` このコードはまず文字列のスライスとして単語のリストを定義します。その後、最初の単語を詩の最初の行として印刷します。2行目は `strings.Join()` 関数を使用して、2行目、3行目、4行目の単語を間隔文字で結合します。最後に、第3行では `strings.Join()` を使用して、残りの単語(第5~第9行)に間隔文字を付けて結合します。

